// Generates tests/fixtures/trigg-openmeteo.json, the FIXED input of the
// Trigg golden test (tests/trigg-golden.test.mjs).
//
//   node tests/fixtures/make-trigg-fixture.mjs
//
// Don't regenerate it casually: the golden snapshot is only meaningful
// against this exact input. The values are synthetic but realistic for
// Trigg in spring, and deliberately varied so every level lands in more
// than one verdict band over the window:
//   27/09  1.4 m / 13 s WSW, easterly land breeze, SW sea breeze from 11h
//   28/09  2.3 m / 15 s groundswell + 0.5 m / 8 s secondary, rip current pm
//   29/09  0.7 m / 10 s, onshore all day (blown out)
//   30/09  1.0 m / 12 s, light winds
// Other dates repeat a quiet 1.1 m / 11 s pattern.
// Wind is in knots, as the app requests (wind_speed_unit=kn).
import { writeFileSync } from "node:fs";

const DATES = [];
for (let d = new Date("2026-09-21T00:00:00Z"); d <= new Date("2026-10-03T00:00:00Z"); d.setUTCDate(d.getUTCDate() + 1)) {
  DATES.push(d.toISOString().slice(0, 10));
}
const DAY = {
  "2026-09-27": { sh: 1.4, sp: 13, sd: 245, sec: null, windy: 1.0, onshore: false, rip: false },
  "2026-09-28": { sh: 2.3, sp: 15, sd: 235, sec: [0.5, 8, 200], windy: 1.0, onshore: false, rip: true },
  "2026-09-29": { sh: 0.7, sp: 10, sd: 250, sec: null, windy: 1.6, onshore: true, rip: false },
  "2026-09-30": { sh: 1.0, sp: 12, sd: 245, sec: null, windy: 0.5, onshore: false, rip: false },
};
const QUIET = { sh: 1.1, sp: 11, sd: 245, sec: null, windy: 0.8, onshore: false, rip: false };
const r = (v, n = 2) => Math.round(v * 10 ** n) / 10 ** n;

const hourly = { time: [] };
const push = (k, v) => (hourly[k] ??= []).push(v);
for (const [di, date] of DATES.entries()) {
  const c = DAY[date] || QUIET;
  for (let h = 0; h < 24; h++) {
    hourly.time.push(`${date}T${String(h).padStart(2, "0")}:00`);
    const seaBreeze = !c.onshore && h >= 11 && h <= 18;
    const kmh = c.onshore ? 30 + 4 * Math.sin(h / 3)
      : seaBreeze ? (8 + 17 * Math.sin(((h - 11) / 7) * Math.PI)) * c.windy
      : (6 + 2 * Math.sin(h / 4)) * c.windy;
    const dir = c.onshore ? 250 : seaBreeze ? 215 : 95 - h;
    push("swell_wave_height", r(c.sh + 0.1 * Math.sin(((h + di) / 24) * 2 * Math.PI)));
    push("swell_wave_period", r(c.sp + 0.3 * Math.cos(h / 5), 1));
    push("swell_wave_direction", c.sd);
    push("secondary_swell_wave_height", c.sec ? c.sec[0] : null);
    push("secondary_swell_wave_period", c.sec ? c.sec[1] : null);
    push("secondary_swell_wave_direction", c.sec ? c.sec[2] : null);
    push("wind_wave_height", r(seaBreeze || c.onshore ? 0.4 + kmh / 60 : 0.15));
    push("wind_wave_period", seaBreeze || c.onshore ? 5 : 3);
    push("wind_wave_direction", seaBreeze || c.onshore ? 225 : 90);
    push("sea_level_height_msl", r(0.5 + 0.3 * Math.sin(((h - 3 + di) / 24) * 2 * Math.PI)));
    push("sea_surface_temperature", 19);
    push("ocean_current_velocity", c.rip && h >= 13 && h <= 17 ? 0.35 : 0.08);
    push("ocean_current_direction", 180);
    push("wind_speed_10m", r(kmh / 1.852));
    push("wind_direction_10m", dir);
    push("wind_gusts_10m", r((kmh * 1.4) / 1.852));
    push("temperature_2m", r(15 + 6 * Math.sin(((h - 8) / 24) * 2 * Math.PI), 1));
    push("precipitation_probability", c.onshore ? 40 : 0);
  }
}
const out = {
  note: "Fixed input for tests/trigg-golden.test.mjs. Generated by make-trigg-fixture.mjs. Synthetic, not recorded.",
  timezone: "Australia/Perth",
  hourly,
  daily: { time: DATES, sunrise: DATES.map((d) => `${d}T05:52`), sunset: DATES.map((d) => `${d}T18:11`) },
};
writeFileSync(new URL("./trigg-openmeteo.json", import.meta.url), JSON.stringify(out) + "\n");
console.log(`${hourly.time.length} hours, ${DATES[0]} -> ${DATES.at(-1)}`);
